// === Tab: mySketch ===
let B = [];
var x;
var y;
var s;
let speed;
let N = 80;
let C = [];  
let c1 = 0;
let c2 = 0;
let run = true;
let F = [];   
let L = -100;

function setup() {
  createCanvas(windowWidth, windowHeight);
  C.push(color(180,230,255,200));
  C.push(color(220,240,200,200));
  C.push(color(255,210,230,200));
  C.push(color(200,240,255,200));

  for (let i = 0; i < N; i++) {
    x = random(-80, 80);
    y = random(-60, 60);
    s = random(3, 8);
    speed = random(0.3, 2);
    B.push([x, y, s, speed]);
  }
  noStroke();
}

function draw() {
  background(20,40,60);
  translate(width/2, height/2);
  if (run) {
    c1 = floor(random(C.length));
    c2 = floor(random(C.length));
  }

  fill(255,255,255,200);
  arc(0,0,220,200,0,PI);
  arc(0,-195,220,20,0,PI);
  rect(-110,-200,220,200);
  rect(-10,70,20,210);

  fill(255,255,255,230);
  triangle(0,270,-80,320,80,320);

  fill(C[c1]);
  rect(-110,L,220,110);
  arc(0,L,220,20,0,PI);

  fill(C[c2]);
  arc(0,0,220,200,0,PI);

  fill(255,240);
  for (let i = 0; i < N; i++) {
    let b = B[i];
    ellipse(b[0], b[1], b[2]);
    b[1] -= b[3];
    if (b[1] < -110) {
      b[1] = 50;
      b[0] = random(-100,100);
    }
  }
  // フルーツ
  for (let f of F) {
  if (f.s === "f") {     
      f.y += f.v;
      f.v += 0.2;
  if (f.y >= -50) {
        f.y = -50;
        f.s = "o"; 
		 f.v = 0;
      }
    } else if (f.s === "o") { 
      f.y = -50 + sin(frameCount*0.05 + f.k) * 5;
      f.x += sin(frameCount*0.04 + f.k) * 0.2;

      if (f.x < -100) f.x = -100;
      if (f.x > 100)  f.x = 100;
    }

    fill(f.c);
    ellipse(f.x, f.y, f.r);
  }
}

function mousePressed() {
  run = !run;

  var x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2;
  var y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2;

  let a = 110, b = 100;
  let inside = (x*x)/(a*a) + (y*y)/(b*b) <= 1;

  if (F.length <5 && inside && y <= 0) {
    F.push({x:x,y:y,r:random(40,60),
      v:0,k:random(1000),
      c:color(random(255,150),random(255,200),random(255,200),200),
      s:"f"
    });
  }
}
